use crate::{MssqlProvider, Parameter, Result, ToSql, metrics_helper::delete_wrap};
use smallvec::SmallVec;
use storm::{BoxFuture, provider::ProviderContainer};

/// Runs the statements generated by `MssqlDelete`, in order, all bound to the same `keys`.
///
/// Not generic so its future is compiled once for all entities. The keys are adapted for
/// tiberius once and shared by all the statements.
#[doc(hidden)]
pub fn _delete<'a>(
    container: &'a ProviderContainer,
    provider: &'a str,
    table: &'static str,
    statements: &'static [&'static str],
    keys: &[&'a dyn ToSql],
) -> BoxFuture<'a, Result<()>> {
    if container.is_noop(provider) {
        return Box::pin(async { Ok(()) });
    }

    let params: SmallVec<[Parameter<'a>; 4]> =
        keys.iter().map(|&k| Parameter(k.to_sql())).collect();

    delete_wrap(
        async move {
            let provider: &MssqlProvider = container.provide(provider).await?;
            let params: SmallVec<[&dyn tiberius::ToSql; 4]> =
                params.iter().map(|p| p as &dyn tiberius::ToSql).collect();

            for sql in statements {
                provider.execute_tds(sql, &params).await?;
            }

            Ok(())
        },
        table,
    )
}
